import{_ as e,c as t,o as d,a2 as a}from"./chunks/framework.DdOM6S6U.js";const w=JSON.parse('{"title":"Middleware","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview"},"headers":[],"relativePath":"system-reference/backend/http/middleware/overview.md","filePath":"system-reference/backend/http/middleware/overview.md","lastUpdated":1778363927000}'),o={name:"system-reference/backend/http/middleware/overview.md"},r=a(`<h1 id="middleware" tabindex="-1">Middleware <a class="header-anchor" href="#middleware" aria-label="Permalink to &quot;Middleware&quot;">​</a></h1><p><strong>Directory</strong>: <code>src/Http/Middleware/</code><br><strong>Registration</strong>: <code>src/Support/ModularousRoutes::generateRouteMiddlewares()</code></p><p>Modularous registers its own middleware aliases and groups during the route bootstrapping phase. All aliases use the <code>modularous.*</code> prefix to avoid conflicts with application middleware.</p><h2 id="middleware-aliases" tabindex="-1">Middleware Aliases <a class="header-anchor" href="#middleware-aliases" aria-label="Permalink to &quot;Middleware Aliases&quot;">​</a></h2><table><thead><tr><th>Alias</th><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><code>modularous.auth</code></td><td><a href="/system-reference/backend/http/middleware/authenticate">AuthenticateMiddleware</a></td><td>Guards routes; stores intended URL; handles JSON 401</td></tr><tr><td><code>modularous.guest</code></td><td><a href="/system-reference/backend/http/middleware/redirect-if-authenticated">RedirectIfAuthenticatedMiddleware</a></td><td>Redirects already-authenticated users away from guest pages</td></tr><tr><td><code>modularous.log</code></td><td><a href="/system-reference/backend/http/middleware/log">LogMiddleware</a></td><td>Injects <code>Request-Id</code> UUID into every request/response</td></tr><tr><td><code>modularous.utm</code></td><td><a href="/system-reference/backend/http/middleware/utm">UtmMiddleware</a></td><td>Captures UTM params and shares them with views</td></tr><tr><td><code>modularous.language</code></td><td><a href="/system-reference/backend/http/middleware/language">LanguageMiddleware</a></td><td>Resolves locale, timezone, and active currency per request</td></tr><tr><td><code>modularous.impersonate</code></td><td><a href="/system-reference/backend/http/middleware/impersonate">ImpersonateMiddleware</a></td><td>Activates user impersonation from session</td></tr><tr><td><code>modularous.loadLocalizedConfig</code></td><td><a href="/system-reference/backend/http/middleware/load-localized-config">LoadLocalizedConfig</a></td><td>Merges deferred and app-level config files at request time</td></tr><tr><td><code>modularous.navigation</code></td><td><a href="/system-reference/backend/http/middleware/navigation">NavigationMiddleware</a></td><td>Shares navigation config with Blade layout views</td></tr><tr><td><code>authorization</code></td><td><a href="/system-reference/backend/http/middleware/authorization">AuthorizationMiddleware</a></td><td>Shares profile/login shortcut schemas with the master layout</td></tr><tr><td><code>modularous.company.registration</code></td><td><a href="/system-reference/backend/http/middleware/company-registration">CompanyRegistrationMiddleware</a></td><td>Guards routes that require a valid company (stub)</td></tr><tr><td><code>modularous.redirector</code></td><td><a href="/system-reference/backend/http/middleware/redirector">RedirectorMiddleware</a></td><td>Consumes a pending redirect URL from <code>RedirectService</code></td></tr><tr><td><code>hostable</code></td><td><a href="/system-reference/backend/http/middleware/hostable">HostableMiddleware</a></td><td>Stub for host-based routing features</td></tr><tr><td><code>inertia.middleware</code></td><td><a href="/system-reference/backend/http/middleware/handle-inertia-requests">HandleInertiaRequests</a></td><td>Inertia root view + shared props (auth, flash, config, store)</td></tr><tr><td><code>role</code></td><td>Spatie <code>RoleMiddleware</code></td><td>Role-based route protection (Spatie Permission)</td></tr><tr><td><code>permission</code></td><td>Spatie <code>PermissionMiddleware</code></td><td>Permission-based route protection (Spatie Permission)</td></tr><tr><td><code>role_or_permission</code></td><td>Spatie <code>RoleOrPermissionMiddleware</code></td><td>Role OR permission route protection (Spatie Permission)</td></tr></tbody></table><h2 id="middleware-groups" tabindex="-1">Middleware Groups <a class="header-anchor" href="#middleware-groups" aria-label="Permalink to &quot;Middleware Groups&quot;">​</a></h2><table><thead><tr><th>Group</th><th>Middleware stack</th></tr></thead><tbody><tr><td><code>web.auth</code></td><td><code>web</code>, <code>modularous.auth:{guard}</code></td></tr><tr><td><code>api.auth</code></td><td><code>api</code>, <code>throttle:api</code>, <code>modularous.auth:{guard}</code></td></tr><tr><td><code>modularous.core</code></td><td><code>modularous.utm</code>, <code>modularous.impersonate</code>, <code>modularous.language</code>, <code>modularous.loadLocalizedConfig</code>, <code>modularous.navigation</code>, <code>inertia.middleware</code></td></tr><tr><td><code>modularous.panel</code></td><td><code>authorization</code>, <code>modularous.company.registration</code>, <code>modularous.redirector</code></td></tr></tbody></table><h2 id="route-stack-by-type" tabindex="-1">Route Stack by Type <a class="header-anchor" href="#route-stack-by-type" aria-label="Permalink to &quot;Route Stack by Type&quot;">​</a></h2><p>Every route registered by Modularous belongs to one of four stacks:</p><table><thead><tr><th>Route type</th><th>Middleware stack</th></tr></thead><tbody><tr><td><code>web</code> (public)</td><td><code>web</code> + <code>modularous.log</code> + <code>modularous.core</code></td></tr><tr><td><code>webPanel</code> (authenticated admin)</td><td><code>web.auth</code> + <code>modularous.log</code> + <code>modularous.core</code> + <code>modularous.panel</code></td></tr><tr><td><code>api</code> (public API)</td><td><code>api</code> + <code>modularous.log</code> + <code>modularous.core</code></td></tr><tr><td><code>apiPanel</code> (authenticated API)</td><td><code>api.auth</code> + <code>modularous.log</code> + <code>modularous.core</code> + <code>modularous.panel</code></td></tr></tbody></table><h2 id="request-flow" tabindex="-1">Request Flow <a class="header-anchor" href="#request-flow" aria-label="Permalink to &quot;Request Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Incoming request</span></span>
<span class="line"><span>  └── modularous.log          ← assign Request-Id UUID</span></span>
<span class="line"><span>  └── modularous.core group</span></span>
<span class="line"><span>        ├── modularous.utm          ← capture UTM params</span></span>
<span class="line"><span>        ├── modularous.impersonate  ← swap auth user if impersonating</span></span>
<span class="line"><span>        ├── modularous.language     ← set locale / currency</span></span>
<span class="line"><span>        ├── modularous.loadLocalizedConfig  ← merge runtime config</span></span>
<span class="line"><span>        ├── modularous.navigation   ← share nav data with views</span></span>
<span class="line"><span>        └── inertia.middleware      ← share auth/flash/config with Inertia</span></span>
<span class="line"><span>  └── [modularous.panel group — authenticated panel routes only]</span></span>
<span class="line"><span>        ├── authorization           ← share profile shortcuts with layout</span></span>
<span class="line"><span>        ├── modularous.company.registration  ← company guard</span></span>
<span class="line"><span>        └── modularous.redirector   ← consume pending redirects</span></span>
<span class="line"><span>  └── Controller</span></span></code></pre></div>`,12),s=[r];function i(n,c,l,u,p,m){return d(),t("div",null,s)}const g=e(o,[["render",i]]);export{w as __pageData,g as default};
